<?php if(!defined('APP_ENTRY'))exit; if($_SERVER['REQUEST_METHOD']!=='GET')deny();$data=rows('SELECT s.name,c.class_name,g.score,g.updated_at FROM grades g JOIN enrollments e ON e.id=g.enrollment_id JOIN students s ON s.id=e.student_id JOIN classes c ON c.id=e.class_id ORDER BY c.class_name,s.name');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="grades.csv"');$f=fopen('php://output','w');fputcsv($f,['Student','Class','Score','Updated'],',','"','');
foreach($data as $r){$safe=array_map(fn($v)=>preg_match('/^[=+\-@\t\r\n]/',(string)$v)?"'".$v:$v,array_values($r));fputcsv($f,$safe,',','"','');}fclose($f);exit;
